    "simple94.lede": "ایک مفید، روزمرہ مصنوعی ذہانت کا ایک تجویز جو آپ خود رکھ سکتے ہیں اور کنٹرول کر سکتے ہیں، بجائے اس کے کہ صرف بڑی کمپنیوں سے کرایہ پر لیں۔",
    "simple94.sections.0.h": "آپ کی AI، آپ کے قواعد",
    "simple94.sections.0.p.0": "Enki کا ماننا ہے کہ آپ کو اپنے ڈیجیٹل ٹولز اور ان کے بنائے ہوئے ڈیٹا کو کنٹرول کرنا چاہیے، نہ کہ صرف چند بڑی کمپنیوں سے AI کرایہ پر لیں۔ مقصد روزمرہ کی AI کو زیادہ قابل رسائی اور ذاتی بنانا ہے، تاکہ یہ آپ کی ضروریات اور اقدار کے مطابق ہو۔",
    "simple94.sections.0.p.1": "یہ نقطہ نظر توازن کی تلاش کرتا ہے: جدید AI سسٹمز کو نگرانی کی ضرورت ہے، لیکن روزمرہ استعمال ہونے والی مددگار AI آپ کے ملکیت والے ہارڈ ویئر پر چلنی چاہیے۔ یہ وژن منصوبے کے ہر دوسرے حصے کو تشکیل دیتا ہے۔",
    "simple94.sections.1.h": "آپ کے آلات کے لیے ایک مشترکہ زبان",
    "simple94.sections.1.p.0": "تجویز کردہ پروٹوکول ایک مشترکہ زبان ہے، نہ کہ کوئی اور AI ماڈل۔ آپ کی اجازت سے، مختلف بنانے والوں کے قابل مطابقت رکھنے والے آلات مل کر کام کریں گے۔ آپ کا فون آپ کے پہلے سے موجود زیادہ قابل کمپیوٹر کو ایک کام بھیج سکتا ہے۔",
    "simple94.sections.1.p.1": "مشترکہ قواعد کنکشنز کا احاطہ کریں گے اور یہ جانچیں گے کہ ماڈل اپ ڈیٹس کہاں سے آتے ہیں، تاکہ ایپس اور ہارڈ ویئر ایک کمپنی کے ایکو سسٹم سے تعلق رکھے بغیر مل کر کام کر سکیں۔",
    "simple94.sections.1.link": "پروٹوکول دیکھیں",
    "simple94.sections.2.h": "وہ ایپ جس سے آپ بات کرتے ہیں",
    "simple94.sections.2.p.0": "کلائنٹ وہ ایپ یا انٹرفیس ہے جسے آپ اپنی AI سے بات کرنے کے لیے استعمال کرتے ہیں۔ Enki کا مقصد اسے اس انجن سے الگ کرنا ہے جو کام کر رہا ہے، تاکہ آپ اپنے فراہم کنندہ کے کلاؤڈ سے بندھے بغیر اپنی ایپ کا انتخاب کر سکیں۔",
    "simple94.sections.2.p.1": "تجویز کردہ کانٹیکسٹ والٹ آپ کے ہارڈ ویئر پر مفید یادداشت رکھے گا، تاکہ ایپس کو تبدیل کرنے کا مطلب دوبارہ شروع کرنا نہ ہو۔ آپ منتخب کرتے ہیں کہ ہر ایپ کس تک رسائی حاصل کر سکتی ہے۔ اگر آپ کلاؤڈ سروس استعمال کرتے ہیں، تو اس کے ساتھ شیئر کی گئی معلومات آپ کے مقامی ماحول سے نکل جاتی ہے۔",
    "simple94.sections.2.link": "کلائنٹ کو دریافت کریں",
    "simple94.sections.3.h": "AI ماڈلز کا انتخاب کرنے کے لیے ایک کیٹلاگ",
    "simple94.sections.3.p.0": "رجسٹری ایک عوامی اسٹارٹر کیٹلاگ ہے جو آپ کو AI ماڈلز کا انتخاب کرنے میں مدد کرنے کے لیے ہے۔ یہ بتاتا ہے کہ ہر ماڈل کیا کرتا ہے، اس کا لائسنس، ہارڈ ویئر کی ضروریات، اور کلاؤڈ یا سیلف ہوسٹنگ کے لیے تخمینی لاگت۔",
    "simple94.sections.3.p.1": "یہ معیار یا بچت کی تصدیق نہیں کرتا، لیکن بانی 300 کمیونٹی کے بڑھنے کے ساتھ بہتر ہونے کا ارادہ رکھتا ہے۔ یہ آپ کو اپنی ضروریات کے لیے صحیح ٹولز کا موازنہ اور انتخاب کرنے میں مدد کرتا ہے۔",
    "simple94.sections.3.link": "رجسٹری براؤز کریں",
    "simple94.sections.4.h": "آپ کی AI کے لیے ایک پورٹیبل گھر",
    "simple94.sections.4.p.0": "Enki ڈیوائس ایک چھوٹے، پورٹیبل کمپیوٹر کا ایک تصور ہے جو خود تعاون یافتہ AI ماڈلز چلاتا ہے۔ آپ کا فون اور ایپس اس سے جڑیں گی، آپ کی مقامی AI کو گھر یا دفتر سے باہر لے جائیں گی۔",
    "simple94.sections.4.p.1": "مقصد یہ ہے کہ لازمی کلاؤڈ اکاؤنٹ کے بغیر تعاون یافتہ کاموں کو سنبھالا جائے۔ کھلے، قابل تعمیر ڈیزائن مختلف مینوفیکچررز کو اسے بنانے کی اجازت دیں گے۔ یہ ابھی دستیاب نہیں ہے، اور ہارڈ ویئر، بجلی اور دیکھ بھال پر اب بھی پیسہ خرچ ہوگا۔",
    "simple94.sections.4.link": "ڈیوائس سے ملیں",
    "simple94.sections.5.h": "AI کے اثر کو سمجھنا",
    "simple94.sections.5.p.0": "Enki انسٹی ٹیوٹ ایک منصوبہ بند تحقیقی ادارہ ہوگا جو AI کے حقیقی دنیا کے اثرات پر نتائج شائع کرے گا۔ یہ مطالعہ کرے گا کہ AI ملازمتوں، ثقافت اور معاشی طاقت کو کیسے بدلتا ہے، نتائج کو openly بانٹتا ہے۔",
    "simple94.sections.5.p.1": "انسٹی ٹیوٹ اینکی کے اپنے خیالات کی جانچ کرے گا اور شواہد کی بنیاد پر مشورہ دے گا۔ اس کا مقصد دوسروں کو ٹیکنالوجی کے بارے میں باخبر فیصلے کرنے میں مدد کرنا ہے۔",
    "simple94.sections.5.link": "انسٹی ٹیوٹ ملاحظہ کریں",
    "simple94.status.h": "پروجیکٹ کی حیثیت",
    "simple94.status.p.0": "مینفیسٹو، پروجیکٹ کی تجاویز، اور ایک اسٹارٹر ماڈل کیٹلاگ عوامی ہیں۔ پروٹوکول، کلائنٹ، پورٹیبل ڈیوائس، اور انسٹی ٹیوٹ کو ابھی بنانا اور جانچنا باقی ہے۔ '300' ان خیالات کو تیار کرنے کے لیے ایک بانی گروپ کا ہدف ہے، نہ کہ موجودہ اراکین کی تعداد۔ کوئی رکنیت فیس نہیں ہے۔",
